(4841927, 702167, 61679, '<td valign="top">Back to comment:  The lighting of this image is exceptional, providing wonderful detail and depth.  One of my favorites this challenge.  9 from me.<br/> <br/>Tim</td>', 'Back to comment:  The lighting of this image is exceptional, providing wonderful detail and depth.  One of my favorites this challenge.  9 from me. Tim', '2008-07-23 22:36:16.000000', NULL, 1),
