(4843195, 702171, 91496, '<td valign="top">Brrr... The slow shutter work well for the water but not so much for the boy.  Still very nice idea and shot.</td>', 'Brrr... The slow shutter work well for the water but not so much for the boy.  Still very nice idea and shot.', '2008-07-24 17:01:26.000000', NULL, 1),
(4843198, 701882, 91496, '<td valign="top">Not a fan of the title.  Ignoring that, it is a nice photo, I can feel the cool seeping into her.  Assuming you had some for of diamond necklace it may have fit the theme better than the perls.  Flash shadow is a minor distraction.</td>', 'Not a fan of the title.  Ignoring that, it is a nice photo, I can feel the cool seeping into her.  Assuming you had some for of diamond necklace it may have fit the theme better than the perls.  Flash shadow is a minor distraction.', '2008-07-24 17:05:00.000000', NULL, 1),
(4843201, 699985, 91496, '<td valign="top">Nice reflection.  Maybe a little too white and frost. Rim of the dish detracts a little.</td>', 'Nice reflection.  Maybe a little too white and frost. Rim of the dish detracts a little.', '2008-07-24 17:06:35.000000', NULL, 1),
