(4843207, 699818, 91496, '<td valign="top">Cool looking, drink up.  Detractions include high noise, halo around glass, and tilted of glass and backdrop horizon.</td>', 'Cool looking, drink up.  Detractions include high noise, halo around glass, and tilted of glass and backdrop horizon.', '2008-07-24 17:10:59.000000', NULL, 1),
