(4843220, 700335, 91496, '<td valign="top">Very ethereal. Not a real cold feeling from me, though.</td>', 'Very ethereal. Not a real cold feeling from me, though.', '2008-07-24 17:15:08.000000', NULL, 1),
(4843223, 701763, 91496, '<td valign="top">Love all the blues and the DOF.  Not feeling really cold though.</td>', 'Love all the blues and the DOF.  Not feeling really cold though.', '2008-07-24 17:16:25.000000', NULL, 1),
(4843226, 699801, 91496, '<td valign="top">Love the natural vignette from the hat and scarf. Great crop.  Wish the eyes were aligned with the horizontal</td>', 'Love the natural vignette from the hat and scarf. Great crop.  Wish the eyes were aligned with the horizontal', '2008-07-24 17:18:43.000000', NULL, 1),
(4843227, 699986, 91496, '<td valign="top">Interesting choice to go greenish when cold is usually associated with blue. Compsotion and DOF are well done.</td>', 'Interesting choice to go greenish when cold is usually associated with blue. Compsotion and DOF are well done.', '2008-07-24 17:19:56.000000', NULL, 1),
(4843233, 702136, 91496, '<td valign="top">Cool idea (pun intended).  Maybe a blue dress to be in the "cool" color family and something other than a string (gold chain perhaps) would have matched the elegance of the rest of the photo.</td>', 'Cool idea (pun intended).  Maybe a blue dress to be in the "cool" color family and something other than a string (gold chain perhaps) would have matched the elegance of the rest of the photo.', '2008-07-24 17:22:56.000000', NULL, 1),
(4843238, 702106, 91496, '<td valign="top">I laughed.  Maybe increase the crop to cover the egdes of the cup.  Otherwise dead on composition.</td>', 'I laughed.  Maybe increase the crop to cover the egdes of the cup.  Otherwise dead on composition.', '2008-07-24 17:25:10.000000', NULL, 1),
(4843241, 702189, 91496, '<td valign="top">Nice photo.  TOo bad it deformed as it froze.  Frame is a distraction.</td>', 'Nice photo.  TOo bad it deformed as it froze.  Frame is a distraction.', '2008-07-24 17:27:07.000000', NULL, 1),
(4843244, 701856, 91496, '<td valign="top">Nice photo.  Good DOF and composition.  I am not feeling a lot of COLD on this one.  There is nothing that cries South Pole instead of Zoo.</td>', 'Nice photo.  Good DOF and composition.  I am not feeling a lot of COLD on this one.  There is nothing that cries South Pole instead of Zoo.', '2008-07-24 17:29:31.000000', NULL, 1),
(4843249, 702078, 91496, '<td valign="top">Great expression and color contrast with the blue and white on the man.  The negative space works on one level but is a boring white on another level.  Frame adds little.</td>', 'Great expression and color contrast with the blue and white on the man.  The negative space works on one level but is a boring white on another level.  Frame adds little.', '2008-07-24 17:32:22.000000', NULL, 1),
(4843252, 701865, 91496, '<td valign="top">Cool bug.  Lots of extra stuff in the photo that detracts from the composition.</td>', 'Cool bug.  Lots of extra stuff in the photo that detracts from the composition.', '2008-07-24 17:34:04.000000', NULL, 1),
(4843255, 701732, 91496, '<td valign="top">I like it.  The textures are great.  Does not really say cold, but white and blue are at least cold colors so it works.  A plain black border may have worked better.</td>', 'I like it.  The textures are great.  Does not really say cold, but white and blue are at least cold colors so it works.  A plain black border may have worked better.', '2008-07-24 17:36:30.000000', NULL, 1),
(4843257, 702097, 91496, '<td valign="top">Nice photo.  DOF is a little too narrow for my taste.  Without the title I would not have recognized them.</td>', 'Nice photo.  DOF is a little too narrow for my taste.  Without the title I would not have recognized them.', '2008-07-24 17:37:31.000000', NULL, 1),
(4843273, 700161, 91496, '<td valign="top">Nice composition.  The uneven frost detracts a bit.  Perhaps this is hard to control.</td>', 'Nice composition.  The uneven frost detracts a bit.  Perhaps this is hard to control.', '2008-07-24 17:47:30.000000', NULL, 1),
(4843276, 702154, 91496, '<td valign="top">Drink up.  The tilt works well.  The bottle is superbly lighted.  I am not a fan of the silver stripe on the glass.</td>', 'Drink up.  The tilt works well.  The bottle is superbly lighted.  I am not a fan of the silver stripe on the glass.', '2008-07-24 17:49:11.000000', NULL, 1),
(4843283, 702217, 91496, '<td valign="top">Superb glass, with great lighting and composition.  The wrinked cloth and black zipper are not so good.  With this on a completely black backgound it would score very high.</td>', 'Superb glass, with great lighting and composition.  The wrinked cloth and black zipper are not so good.  With this on a completely black backgound it would score very high.', '2008-07-24 17:52:30.000000', NULL, 1),
(4843285, 702185, 91496, '<td valign="top">Nice abstact.  I like all the textures.  Not a fan or the border.</td>', 'Nice abstact.  I like all the textures.  Not a fan or the border.', '2008-07-24 17:53:37.000000', NULL, 1),
