(4844520, 702071, 69192, '<td valign="top">Interesting take on the subject!</td>', 'Interesting take on the subject!', '2008-07-25 13:34:47.000000', NULL, 1),
(4844523, 700355, 62249, '<td valign="top">With global warming &amp; all, I''m surprised there''s much Mendenhall left (I''m a former Alaskan). Nice processing on this one.</td>', 'With global warming & all, I''m surprised there''s much Mendenhall left (I''m a former Alaskan). Nice processing on this one.', '2008-07-25 13:36:14.000000', NULL, 1),
